INSERT INTO messages (for_name, text) VALUES ('Florian', 'Nicht dein Lieblingsteil vom Tag, das wissen wir. Danke, dass du''s trotzdem machst');
INSERT INTO messages (for_name, text) VALUES ('Florian', 'erledigt, bevor die nächste Gaming-Session startet – Zeitmanagement-Skills: legendary');
